// BLOCK 4 — "A location slips, the dashboard catches it"
// A hero line chart trends steady, then dips (the slip); the dashboard catches
// it with a pulsing alert ring before a monthly-review marker; a 3-way
// diagnostic row then finds the cause (competitor priced lower).
import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
} from "remotion";
import {
  springIn,
  staggeredSpring,
  drawPath,
  ambientDrift,
} from "../motion";

export const fps = 25;
export const durationInFrames = 358;

const COLORS = {
  bg: "#161718",
  card: "#1d1e1f",
  border: "#3d3f43",
  text: "#f4f4f5",
  textMuted: "#bfc1c5",
  textSubtle: "#8c93a8",
  orange: "#F86606",
  orangeDeep: "#FF4800",
  orangeTint: "rgba(248,102,6,0.16)",
};
const RED = "#FF3B30";
const FONT_MARKETING = "'GT Walsheim', Inter, sans-serif";
const FONT_MONO = "monospace";

// ---- exact cue frames ------------------------------------------------------
const CUE_LINE = 0;
const CUE_DIP = 33;
const CUE_RING = 61;
const CUE_CALLOUT = 92;
const CUE_MARKER = 112;
const CUE_CARDS = 151;
const CUE_A = 186;
const CUE_B = 215;
const CUE_C = 255;
const CUE_RESOLVE = 300;

// ---- small geometry helpers ------------------------------------------------
type P = { x: number; y: number };
function polyLen(pts: P[]): number {
  let L = 0;
  for (let i = 1; i < pts.length; i++) {
    L += Math.hypot(pts[i].x - pts[i - 1].x, pts[i].y - pts[i - 1].y);
  }
  return L;
}
function pathFrom(pts: P[]): string {
  return pts.map((p, i) => `${i === 0 ? "M" : "L"} ${p.x.toFixed(2)} ${p.y.toFixed(2)}`).join(" ");
}

// ===========================================================================
// DIAGNOSTIC CARD viz — Competitor (bar comparison)
// ===========================================================================
const CompetitorViz: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();
  const base = Math.min(width, height);
  const fill = springIn(frame, vfps, CUE_A, "LIQUID");
  const deltaIn = springIn(frame, vfps, CUE_A + 8, "SNAPPY");

  const rows = [
    { label: "You", frac: 0.5, color: COLORS.border, txt: COLORS.textMuted },
    { label: "Rival", frac: 0.82, color: COLORS.orange, txt: COLORS.text },
  ];
  const barH = base * 0.028;
  const labelSize = base * 0.016;

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: base * 0.024, width: "100%" }}>
      {rows.map((r, i) => (
        <div key={i} style={{ display: "flex", alignItems: "center", gap: base * 0.014 }}>
          <div
            style={{
              width: base * 0.06,
              fontFamily: FONT_MONO,
              fontSize: labelSize,
              color: r.txt,
              fontWeight: 600,
              letterSpacing: "0.02em",
            }}
          >
            {r.label}
          </div>
          <div
            style={{
              flex: 1,
              height: barH,
              background: "#111213",
              borderRadius: barH / 2,
              overflow: "hidden",
              position: "relative",
            }}
          >
            <div
              style={{
                position: "absolute",
                left: 0,
                top: 0,
                bottom: 0,
                width: `${r.frac * fill * 100}%`,
                background: r.color,
                borderRadius: barH / 2,
              }}
            />
          </div>
          {r.label === "Rival" && (
            <div
              style={{
                width: base * 0.055,
                textAlign: "right",
                fontFamily: FONT_MONO,
                fontSize: labelSize,
                fontWeight: 700,
                color: COLORS.orange,
                opacity: deltaIn,
              }}
            >
              −20%
            </div>
          )}
        </div>
      ))}
    </div>
  );
};

// ===========================================================================
// DIAGNOSTIC CARD viz — Sentiment (line dips)
// ===========================================================================
const SentimentViz: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();
  const pts: P[] = [
    { x: 6, y: 16 },
    { x: 28, y: 13 },
    { x: 50, y: 20 },
    { x: 72, y: 31 },
    { x: 94, y: 41 },
  ];
  const len = polyLen(pts);
  const draw = drawPath(frame, vfps, len, { delay: CUE_B, preset: "SNAPPY" });
  const lineProg = springIn(frame, vfps, CUE_B, "SNAPPY");
  const endReveal = interpolate(lineProg, [0.75, 1], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const last = pts[pts.length - 1];

  return (
    <svg viewBox="0 0 100 50" width="100%" height="100%" style={{ display: "block" }} preserveAspectRatio="none">
      <line x1={4} y1={45} x2={96} y2={45} stroke={COLORS.border} strokeWidth={0.5} strokeOpacity={0.6} />
      {[15, 30].map((gy) => (
        <line key={gy} x1={4} y1={gy} x2={96} y2={gy} stroke={COLORS.border} strokeWidth={0.4} strokeOpacity={0.35} />
      ))}
      <path d={pathFrom(pts)} fill="none" stroke={COLORS.orange} strokeWidth={1.4} strokeLinecap="round" strokeLinejoin="round" {...draw} />
      <circle cx={last.x} cy={last.y} r={2} fill={COLORS.orange} opacity={endReveal} />
    </svg>
  );
};

// ===========================================================================
// DIAGNOSTIC CARD viz — Operational (gauge fills)
// ===========================================================================
const OperationalViz: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();
  const base = Math.min(width, height);
  const prog = springIn(frame, vfps, CUE_C, "LIQUID");
  const fillFrac = 0.98;
  const R = 42;
  const arcLen = Math.PI * R;
  const arc = "M 8 54 A 42 42 0 0 1 92 54";
  const val = Math.round(prog * 98);

  return (
    <div style={{ position: "relative", width: "100%", height: "100%", display: "flex", alignItems: "center", justifyContent: "center" }}>
      <svg viewBox="0 0 100 62" width="82%" style={{ display: "block", overflow: "visible" }}>
        <path d={arc} fill="none" stroke="#111213" strokeWidth={7} strokeLinecap="round" />
        <path
          d={arc}
          fill="none"
          stroke={COLORS.orange}
          strokeWidth={7}
          strokeLinecap="round"
          strokeDasharray={arcLen}
          strokeDashoffset={arcLen * (1 - prog * fillFrac)}
        />
      </svg>
      <div
        style={{
          position: "absolute",
          top: "58%",
          left: 0,
          right: 0,
          textAlign: "center",
          fontFamily: FONT_MARKETING,
          fontWeight: 600,
          fontSize: base * 0.05,
          color: COLORS.text,
          letterSpacing: "-0.02em",
          fontVariantNumeric: "tabular-nums",
          opacity: Math.min(1, prog * 3),
        }}
      >
        {val}%
      </div>
    </div>
  );
};

// ===========================================================================
// DIAGNOSTIC CARD shell
// ===========================================================================
const DiagCard: React.FC<{
  index: number;
  x: number;
  y: number;
  w: number;
  h: number;
  title: string;
  subtitle: string;
  isCulprit: boolean;
  highlightCue?: number;
  children: React.ReactNode;
}> = ({ index, x, y, w, h, title, subtitle, isCulprit, highlightCue, children }) => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();
  const base = Math.min(width, height);

  const cardIn = staggeredSpring(frame, vfps, index, CUE_CARDS, 10, "LIQUID");
  const entryTy = interpolate(cardIn, [0, 1], [base * 0.03, 0]);
  const resolve = springIn(frame, vfps, CUE_RESOLVE, "LIQUID");
  const driftY = ambientDrift(frame, 1.6, 120 + index * 14, `card-${index}`);

  const dataHi = highlightCue != null ? springIn(frame, vfps, highlightCue, "SNAPPY") : 0;
  const emph = Math.max(dataHi * 0.7, isCulprit ? resolve : 0);
  const dim = isCulprit ? 1 : 1 - resolve * 0.68;

  const titleSize = base * 0.024;
  const subSize = base * 0.017;

  return (
    <div
      style={{
        position: "absolute",
        left: x,
        top: y,
        width: w,
        height: h,
        background: COLORS.card,
        border: `2px solid ${COLORS.border}`,
        borderRadius: base * 0.016,
        padding: base * 0.026,
        display: "flex",
        flexDirection: "column",
        gap: base * 0.02,
        opacity: cardIn * dim,
        transform: `translateY(${entryTy + driftY}px)`,
        boxShadow:
          emph > 0.01
            ? `0 0 ${base * 0.03 * emph}px rgba(248,102,6,${0.38 * emph}), inset 0 0 0 ${2.5 * emph}px ${COLORS.orange}`
            : "none",
      }}
    >
      <div style={{ display: "flex", alignItems: "baseline", gap: base * 0.01 }}>
        <div
          style={{
            fontFamily: FONT_MARKETING,
            fontWeight: 600,
            fontSize: titleSize,
            color: emph > 0.3 ? COLORS.orange : COLORS.text,
            letterSpacing: "-0.01em",
          }}
        >
          {title}
        </div>
        <div
          style={{
            fontFamily: FONT_MONO,
            fontWeight: 500,
            fontSize: subSize,
            color: COLORS.textSubtle,
            letterSpacing: "0.02em",
          }}
        >
          {subtitle}
        </div>
      </div>
      <div style={{ flex: 1, display: "flex", alignItems: "center", minHeight: 0 }}>{children}</div>
    </div>
  );
};

// ===========================================================================
// MAIN SCENE
// ===========================================================================
const Block4: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();
  const base = Math.min(width, height);

  // ---- layout ------------------------------------------------------------
  const CONTENT_W = Math.round(width * 0.72);
  const CONTENT_X = Math.round((width - CONTENT_W) / 2);
  const PANEL_PAD = Math.round(base * 0.028);
  const titleH = Math.round(base * 0.06);
  const chartW = CONTENT_W - PANEL_PAD * 2;

  const VBW = 100;
  const VBH = 34;
  const chartH = Math.round((chartW * VBH) / VBW);
  const heroX = CONTENT_X;
  const heroY = Math.round(base * 0.06);
  const heroW = CONTENT_W;
  const heroH = PANEL_PAD + titleH + chartH + PANEL_PAD;

  const diagGap = Math.round(base * 0.03);
  const diagY = heroY + heroH + Math.round(base * 0.045);
  const diagH = Math.round(base * 0.3);
  const cardW = Math.round((CONTENT_W - diagGap * 2) / 3);

  // ---- chart plot region (viewBox units) ---------------------------------
  const plotL = 6;
  const plotR = 94;
  const plotT = 5;
  const plotB = 29;
  const VALS = [0.45, 0.52, 0.48, 0.58, 0.55, 0.64, 0.68, 0.72, 0.34];
  const N = VALS.length;
  const DIP_FRAC = 0.72;
  const pts: P[] = VALS.map((v, i) => {
    const f = (i / (N - 1)) * DIP_FRAC;
    return { x: plotL + f * (plotR - plotL), y: plotB - v * (plotB - plotT) };
  });
  const steadyPts = pts.slice(0, N - 1); // points 0..7 (orange)
  const dipSeg = [pts[N - 2], pts[N - 1]]; // 7 -> 8 (red)
  const dip = pts[N - 1];
  const steadyLen = polyLen(steadyPts);
  const dipLen = polyLen(dipSeg);

  // viewBox -> % of chartBox
  const pctX = (vx: number) => (vx / VBW) * 100;
  const pctY = (vy: number) => (vy / VBH) * 100;
  const markerVX = plotL + 0.9 * (plotR - plotL);

  // ---- animation state ---------------------------------------------------
  const panelIn = springIn(frame, vfps, CUE_LINE, "LIQUID");
  const panelTy = interpolate(panelIn, [0, 1], [base * 0.02, 0]);
  const panelSc = interpolate(panelIn, [0, 1], [0.98, 1]);
  const heroDriftX = ambientDrift(frame, 1.6, 150, "hero-x");
  const heroDriftY = ambientDrift(frame, 1.6, 130, "hero-y");

  const axisIn = springIn(frame, vfps, CUE_LINE + 2, "GENTLE");
  const lineProg = springIn(frame, vfps, CUE_LINE, "LIQUID");
  const steadyDraw = drawPath(frame, vfps, steadyLen, { delay: CUE_LINE, preset: "LIQUID" });
  const dipDraw = drawPath(frame, vfps, dipLen, { delay: CUE_DIP, preset: "SNAPPY" });

  const dipIn = springIn(frame, vfps, CUE_DIP, "SNAPPY");
  const dipEmph = springIn(frame, vfps, CUE_CALLOUT, "ELASTIC");
  const baseDipR = 1.0;
  const dipR = baseDipR * (dipIn + dipEmph * 0.7);
  const dropOp = dipIn * 0.4;

  // alert ring (c43c47ef pulsing-ring technique) — red + offset orange
  const ringActive = frame >= CUE_RING;
  const ringTrigger = springIn(frame, vfps, CUE_RING, "SNAPPY");
  const period = 22;
  const pulse = ringActive ? ((frame - CUE_RING) % period) / period : 0;
  const pulse2 = ringActive ? ((frame - CUE_RING + 11) % period) / period : 0;
  const ringR = baseDipR * (1.5 + pulse * 3.2);
  const ringR2 = baseDipR * (1.5 + pulse2 * 3.2);
  const ringOp = ringActive ? ringTrigger * (1 - pulse) * 0.8 : 0;
  const ringOp2 = ringActive ? ringTrigger * (1 - pulse2) * 0.45 : 0;

  const catchGlow = springIn(frame, vfps, CUE_RING, "SNAPPY");

  // callout "▼ 12%"
  const calloutIn = springIn(frame, vfps, CUE_CALLOUT, "ELASTIC");
  const calloutDrift = ambientDrift(frame, 1.4, 90, "callout");

  // monthly-review marker (slides in from the right)
  const markerIn = springIn(frame, vfps, CUE_MARKER, "LIQUID");
  const markerTx = interpolate(markerIn, [0, 1], [chartW * 0.12, 0]);

  const dashW = Math.max(4, base * 0.0028);
  const calSize = base * 0.03;
  const markerLabelSize = base * 0.016;
  const titleSize = base * 0.026;
  const statusPulse = 0.55 + 0.45 * Math.abs(Math.sin(frame / 12));

  return (
    <AbsoluteFill>
      {/* ---- HERO PANEL ---- */}
      <div
        style={{
          position: "absolute",
          left: heroX,
          top: heroY,
          width: heroW,
          height: heroH,
          background: COLORS.card,
          border: `2px solid ${COLORS.border}`,
          borderRadius: base * 0.02,
          opacity: panelIn,
          transform: `translate(${heroDriftX}px, ${panelTy + heroDriftY}px) scale(${panelSc})`,
          boxShadow: `0 ${base * 0.01}px ${base * 0.03}px rgba(0,0,0,0.45), 0 0 ${base * 0.02 * catchGlow}px rgba(255,59,48,${0.18 * catchGlow})`,
        }}
      >
        {/* panel title */}
        <div
          style={{
            position: "absolute",
            left: PANEL_PAD,
            top: PANEL_PAD,
            display: "flex",
            alignItems: "center",
            gap: base * 0.012,
          }}
        >
          <div
            style={{
              width: base * 0.011,
              height: base * 0.011,
              borderRadius: "50%",
              background: COLORS.orange,
              opacity: statusPulse,
            }}
          />
          <div
            style={{
              fontFamily: FONT_MARKETING,
              fontWeight: 600,
              fontSize: titleSize,
              color: COLORS.text,
              letterSpacing: "-0.01em",
            }}
          >
            Store 14 · Revenue
          </div>
        </div>

        {/* chart box */}
        <div
          style={{
            position: "absolute",
            left: PANEL_PAD,
            top: PANEL_PAD + titleH,
            width: chartW,
            height: chartH,
          }}
        >
          <svg viewBox={`0 0 ${VBW} ${VBH}`} width="100%" height="100%" preserveAspectRatio="none" style={{ display: "block", overflow: "visible" }}>
            {/* faint gridlines */}
            {[0.25, 0.5, 0.75].map((g) => {
              const gy = plotT + g * (plotB - plotT);
              return (
                <line key={`h${g}`} x1={plotL} y1={gy} x2={plotR} y2={gy} stroke={COLORS.border} strokeWidth={0.12} strokeOpacity={0.5 * axisIn} />
              );
            })}
            {[0.25, 0.5, 0.75].map((g) => {
              const gx = plotL + g * (plotR - plotL);
              return (
                <line key={`v${g}`} x1={gx} y1={plotT} x2={gx} y2={plotB} stroke={COLORS.border} strokeWidth={0.1} strokeOpacity={0.28 * axisIn} />
              );
            })}
            {/* axes / baseline */}
            <line x1={plotL} y1={plotB} x2={plotR} y2={plotB} stroke={COLORS.border} strokeWidth={0.2} strokeOpacity={axisIn} />
            <line x1={plotL} y1={plotT} x2={plotL} y2={plotB} stroke={COLORS.border} strokeWidth={0.2} strokeOpacity={axisIn} />

            {/* red drop-line from dip to baseline */}
            <line x1={dip.x} y1={dip.y} x2={dip.x} y2={plotB} stroke={RED} strokeWidth={0.14} strokeDasharray="0.8 0.8" opacity={dropOp} />

            {/* steady (orange) line */}
            <path d={pathFrom(steadyPts)} fill="none" stroke={COLORS.orange} strokeWidth={0.5} strokeLinecap="round" strokeLinejoin="round" {...steadyDraw} />

            {/* dip (red) segment */}
            {frame >= CUE_DIP && (
              <path d={pathFrom(dipSeg)} fill="none" stroke={RED} strokeWidth={0.62} strokeLinecap="round" strokeLinejoin="round" {...dipDraw} />
            )}

            {/* node dots along steady line */}
            {steadyPts.map((p, i) => {
              const reveal = lineProg * (steadyPts.length - 1) - i;
              const op = interpolate(reveal, [0, 0.5], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
              return <circle key={i} cx={p.x} cy={p.y} r={0.55} fill={COLORS.orange} opacity={op} />;
            })}

            {/* pulsing alert rings on the dip point */}
            {ringActive && (
              <>
                <circle cx={dip.x} cy={dip.y} r={ringR} fill="none" stroke={RED} strokeWidth={0.4} opacity={ringOp} />
                <circle cx={dip.x} cy={dip.y} r={ringR2} fill="none" stroke={COLORS.orange} strokeWidth={0.32} opacity={ringOp2} />
              </>
            )}

            {/* dip point (emphasized) */}
            {frame >= CUE_DIP && <circle cx={dip.x} cy={dip.y} r={dipR} fill={RED} />}
          </svg>

          {/* callout "▼ 12%" */}
          {frame >= CUE_CALLOUT && (
            <div
              style={{
                position: "absolute",
                left: `${pctX(dip.x)}%`,
                top: `${pctY(dip.y)}%`,
                transform: `translate(-50%, calc(-165% + ${calloutDrift}px)) scale(${interpolate(calloutIn, [0, 1], [0.7, 1])})`,
                opacity: calloutIn,
                background: COLORS.orangeTint,
                border: `2px solid ${COLORS.orange}`,
                borderRadius: base * 0.01,
                padding: `${base * 0.005}px ${base * 0.012}px`,
                fontFamily: FONT_MARKETING,
                fontWeight: 700,
                fontSize: base * 0.02,
                color: COLORS.orange,
                whiteSpace: "nowrap",
                letterSpacing: "-0.01em",
              }}
            >
              ▼ 12%
            </div>
          )}

          {/* monthly-review marker (slides in from right, sits right of the dip) */}
          {frame >= CUE_MARKER && (
            <div
              style={{
                position: "absolute",
                left: `${pctX(markerVX)}%`,
                top: `${pctY(plotT)}%`,
                height: `${pctY(plotB) - pctY(plotT)}%`,
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                transform: `translateX(calc(-50% + ${markerTx}px))`,
                opacity: markerIn,
              }}
            >
              {/* calendar glyph */}
              <svg width={calSize} height={calSize} viewBox="0 0 24 24" style={{ display: "block", flexShrink: 0 }}>
                <rect x={3} y={5} width={18} height={16} rx={3} fill="none" stroke={COLORS.textMuted} strokeWidth={1.8} />
                <line x1={3} y1={9.5} x2={21} y2={9.5} stroke={COLORS.textMuted} strokeWidth={1.8} />
                <line x1={8} y1={3} x2={8} y2={7} stroke={COLORS.textMuted} strokeWidth={1.8} strokeLinecap="round" />
                <line x1={16} y1={3} x2={16} y2={7} stroke={COLORS.textMuted} strokeWidth={1.8} strokeLinecap="round" />
                <circle cx={8} cy={14} r={1.3} fill={COLORS.textMuted} />
                <circle cx={12} cy={14} r={1.3} fill={COLORS.textMuted} />
              </svg>
              <div
                style={{
                  marginTop: base * 0.006,
                  marginBottom: base * 0.006,
                  fontFamily: FONT_MARKETING,
                  fontWeight: 600,
                  fontSize: markerLabelSize,
                  color: COLORS.textMuted,
                  letterSpacing: "-0.005em",
                  whiteSpace: "nowrap",
                }}
              >
                Monthly review
              </div>
              <div style={{ flex: 1, width: 0, borderLeft: `${dashW}px dashed ${COLORS.textSubtle}`, opacity: 0.85 }} />
            </div>
          )}
        </div>
      </div>

      {/* ---- DIAGNOSTIC ROW ---- */}
      <DiagCard
        index={0}
        x={CONTENT_X}
        y={diagY}
        w={cardW}
        h={diagH}
        title="Competitor"
        subtitle="· price"
        isCulprit={true}
        highlightCue={CUE_A}
      >
        <CompetitorViz />
      </DiagCard>

      <DiagCard
        index={1}
        x={CONTENT_X + cardW + diagGap}
        y={diagY}
        w={cardW}
        h={diagH}
        title="Sentiment"
        subtitle="· 30d"
        isCulprit={false}
      >
        <SentimentViz />
      </DiagCard>

      <DiagCard
        index={2}
        x={CONTENT_X + (cardW + diagGap) * 2}
        y={diagY}
        w={cardW}
        h={diagH}
        title="Operational"
        subtitle="· uptime"
        isCulprit={false}
      >
        <OperationalViz />
      </DiagCard>
    </AbsoluteFill>
  );
};

export default Block4;
